    ["01-2"] = {name="Durotar", nameA="Durotar: {a:367} & {a:362}", shortA="Durotar: {a:367} +", tips={{k="取捨", text="Faça Carregue suas tralhas. Colete Retalho de Lona junto com os outros objetivos Bastilha Tiragarde."}, {k="取捨", text="Entregue Aniquile os invasores para desbloquear Dos destroços.... Faça isso junto com Um espírito solvente."}, {k="取捨", text="Salve a cadeia de masmorras Antro das Sombras. Se você planeja executar Cavernas Ígneas, pegue Inimigos ocultos ( → →) de Thrall. Obtenha o distintivo para no acampamento Lâmina Ardente ao norte."}, {k="提醒", text="Abaixo do nível 12? Faça Faça o que eu digo..., Rocha da Caveira ou as primeiras missões Ameaça from Below.", s={{"Abaixo do nível 12?"}, {"Faça Faça o que eu digo..., Rocha da Caveira ou as primeiras missões Ameaça from Below"}}}}, danger={[1]="As escadas e portas em Bastilha Tiragarde podem puxar os marinheiros do andar de cima. Limpe a parede externa e a entrada primeiro.", [2]="Gigantes marinhos vagam pela área das nagas na costa norte. Limpe os mobs próximos antes de puxar um. Retire-se ao longo da costa se tiver problemas."}, grind={[1]={mob="Fuzileiro de Kul Tiraz", note="Mobs normais densos em Bastilha Tiragarde. Puxe para fora para evitar acréscimos nos corredores. Colete Retalho de Lona para a nova bolsa."}, [2]={mob="Guarda de Batalha Crinavalha", note="Mobs normais se aglomeram a oeste de Monte Navalha. Siga ao longo da borda do acampamento e observe as patrulhas. Emparelhe com Invasão."}, [3]={mob="Bruxa da Tempestade Sopravento", note="Agrupamento de mobs normais no norte de Durotar. Use a cobertura para aproximar os rodízios. Faça Faça o que eu digo... ou triture até 12 antes de Orgrimmar."}}, supply={[1]={npc="Trayexir"}, [2]={npc="Estalajadeiro Grosk"}, [3]={npc="Wuark"}, [4]={npc="Estalajadeiro Grosk"}, [5]={npc="Ghrawt"}, [6]={npc="Doraso"}}, steps={[1]={npc="Ukor", tgt="Ukor", desc="Procure Ukor na estrada de Vale das Provações a Aldeia Sen'jin."}, [2]={hint="Fale com o Mestre Gad