"}, [77]={npc="Gar'Thok", tgt="Gar'Thok"}, [78]={text="Oeste de Monte Navalha e norte de Durotar"}, [79]={hint="Mate 4 Javatuscos Crinavalha, 4 Batedores Crinavalha, 4 Levanta-poeira Crinavalha e 4 Guardas de Batalha Crinavalha para Gar'Thok no Monte Navalha."}, [80]={hint="O Cozinheiro Torka no Monte Navalha quer que você colete 8 Peras Espinhosas nas Terras Crinavalha a oeste da cidade."}, [81]={npc="Gar'Thok", tgt="Gar'Thok"}, [82]={npc="Cozinheiro Torka", tgt="Cozinheiro Torka"}, [83]={npc="Orgnil Chaganalma", tgt="Orgnil Chaganalma", desc="Min. Nível 9."}, [84]={hint="Encontre Heglan Sombrolho ao norte da Bastilha Tiragarde.", desc="Min. Nível 9."}, [85]={npc="Heglan Sombrolho", tgt="Heglan Sombrolho", desc="Min. Nível 9."}, [86]={npc="Heglan Sombrolho", tgt="Heglan Sombrolho"}, [87]={hint="Encontre sinais do que atacou Heglan Sombrolho."}, [88]={npc="Orgnil Chaganalma", tgt="Orgnil Chaganalma"}, [89]={npc="Orgnil Chaganalma", tgt="Orgnil Chaganalma"}, [90]={hint="Leve a Garra do Bulho para Orgnil Chaganalma no Monte Navalha."}, [91]={hint="Colete 9 Espinhapinas de Naga."}, [92]={npc="Orgnil Chaganalma", tgt="Orgnil Chaganalma"}, [93]={npc="Orgnil Chaganalma", tgt="Orgnil Chaganalma"}, [94]={npc="Orgnil Chaganalma", tgt="Orgnil Chaganalma", tag="Opcional", desc="Gigante marinho de elite na costa norte. Agrupe ou pule, se necessário."}, [95]={hint="Mate o Gigante do Mar na costa norte de Durotar e traga uma prova do seu feito.", tag="Opcional", desc="Gigante marinho de elite na costa norte. Agrupe ou pule, se necessário."}, [96]={npc="Orgnil Chaganalma", tgt="Orgnil Chaganalma", tag="Opcional", desc="Gigante marinho de elite na costa norte. Agrupe ou pule, se necessário."}, [97]={npc="Orgnil Chaganalma", tgt="Orgnil Chaganalma"}, [98]={hint="Fale com Margoz."}, [99]={npc="Margoz", tgt="Margoz"}, [100]={npc="Margoz", tgt="Margoz"}, [101]={hint="Junte Colares Calcinantes dos sectários na Rocha da Caveira."}, [102]={npc="Margoz", tgt="Margoz"}, [103]={npc="Margoz", tgt="Margoz", tag="Opcional"}, [104]={text="EXP opcional antes do nível 12"}, [105]={npc="Rezlak", tgt="Rezlak", tag="Opcional"}, [106]={hint="Recupere 5 Sacos de Suprimentos e entregue-os a Rezlak perto de Orgrimmar.", tag="Opcional"}, [107]={npc="Rezlak", tgt="Rezlak", tag="Opcional"}, [108]={npc="Rezlak", tgt="Rezlak", tag="Opcional"}, [109]={hint="Mate 12 Selvagens Sopravento e 8 Bruxas da Tempestade Sopravento para Rezlak perto do Barranco da Ravina Seca.", tag="Opcional"}, [110]={npc="Rezlak", tgt="Rezlak", tag="Opcional"}, [111]={npc="Misha Tor'kren", tgt="Misha Tor'kren", tag="Opcional"}, [112]={hint="Leve uma prova do destino de Kron para Misha Tor'kren na fazenda a noroeste do Monte Navalha.", tag="Opcional"}, [113]={npc="Misha Tor'kren", tgt="Misha Tor'kren", tag="Opcional"}, [114]={npc="Orbe da Tempestade Opaco", npcObj=true, tag="Opcional", desc="Aceite apenas se você saquear o Orbe da Tempestade Opaco."}, [115]={hint="Leve o Orbe da Tempestade Opaco para Rezlak perto do Barranco da Ravina Seca.", tag="Opcional", desc="Aceite apenas se você saquear o Orbe da Tempestade Opaco."}, [116]={npc="Rezlak", tgt="Rezlak", tag="Opcional", desc="Aceite apenas se você saquear o Orbe da Tempestade Opaco."}, [117]={npc="Rezlak", tgt="Rezlak", tag="Opcional"}, [118]={hint="Leve 5 Órgãos de Lagarto Trovejante Carregados para Rezlak perto do Barranco da Ravina Seca.", tag="Opcional"}, [119]={npc="Rezlak", tgt="Rezlak", tag="Opcional"}, [120]={npc="Casco de Halikor", npcObj=true, tag="Opcional", desc="Se você encontrar Halikor e conseguir vencê-lo, saqueie seu casco."}, [121]={text="Captadores Orgrimmar e handoff A Encruzilhada"}, [122]={text="Para missões ou treinamento Orgrimmar, siga a estrada principal para o norte através do portão sul. Aprenda ponto de voo de Doraso (45.12, 63.89) e entregue missões próximas."}, [123]={hint="Entregue as Ordens do Almirante Proudmore a Nazgrel nos aposentos de Thrall, em Orgrimmar.", tag="Opcional"}, [124]={npc="Nazgrel", tgt="Nazgrel", tag="Opcional"}, [125]={hint="Leve um Colar de Amostra para Neeru Cortafogo em Orgrimmar.", tag="Opcional"}, [126]={npc="Neeru Cortafogo", tgt="Neeru Cortafogo", tag="Opcional"}, [127]={hint="Fale com Thuwd em Orgrimmar para aprender a criar um item de acampamento para a sua profissão quando demonstrar proficiência nessa perícia.", tag="Opcional"}, [128]={npc="Thuwd", tgt="Thuwd", tag="Opcional"}, [129]={hint="Leve o Casco de Halikor para Orgrimmar.", tag="Opcional"}, [130]={npc="Kamari", tgt="Kamari", tag="Opcional"}, [131]={text="Após a entrega da missão da cidade, siga para Monte Navalha ou corra para o sul ao longo da estrada principal. Pule esta viagem se você ficou fora da cidade."}, [132]={npc="Takrin Buscatrilha", tgt="Takrin Buscatrilha", desc="Requer nível 10. Espere até cerca de 12 para ir para o A Encruzilhada."}, [133]={hint="Siga a estrada a oeste, de Monte Navalha para os Sertões, passando por uma ponte."}, [134]={npc="Kargal Chaga de Guerra", tgt="Kargal Chaga de Guerra"}, [135]={npc="Kargal Chaga de Guerra", tgt="Kargal Chaga de Guerra"}, [136]={text="Vá para oeste a partir de Posto Remoto. Vire para o sul no entroncamento para A Encruzilhada."}, [137]={hint="Siga a estrada a oeste a partir do Posto Remoto de Kargal."}, [138]={npc="Sergra Espinhonegro", tgt="Sergra Espinhonegro"}, [139]={npc="Kaplak", tgt="Kaplak", desc="Pão ralado Orc. Os trolls podem pegar A Mão Despedaçada diretamente de Therzok."}, [140]={hint="Fale com Therzok no Antro das Sombras em Orgrimmar.", desc="Pão ralado Orc. Os trolls podem pegar A Mão Despedaçada diretamente de Therzok."}, [141]={npc="Therzok", tgt="Therzok", desc="Pão ralado Orc. Os trolls podem pegar A Mão Despedaçada diretamente de Therzok."}, [142]={npc="Therzok", tgt="Therzok", desc="Roube Chave de Tazan primeiro e depois pegue seu pacote. Guarde a chave para o acompanhamento."}, [143]={hint="Mate Tazan e leve a Algibeira dele para Therzok no Antro das Sombras, que fica em Orgrimmar.", desc="Roube Chave de