, [90]={hint="Mate 14 Trabalhadores da Empreendimentos S.A. e 6 Supervisores da Empreendimentos S.A. para Morin Espreita Nuvem na Aldeia Casco Sangrento."}, [91]={hint="Mate o Supervisor Geringonça e leve sua prancheta para Morin Espreita Nuvem na Aldeia Casco Sangrento."}, [92]={npc="Planos de Expansão de Mulgore", npcObj=true, tag="Opcional", desc="Saqueie Planos de Expansão de Mulgore de Supervisor Geringonça para iniciar a missão."}, [93]={hint="Colete o restante das páginas do Supervisor Geringonça dentro da Mina da Empreendimentos S.A. e leve-as a Morin Espreita Nuvem, perto da Aldeia Casco Sangrento.", tag="Opcional", desc="Colete todas as três notas dentro da Venture Co. Mina antes de sair."}, [94]={hint="Derrote Chakuyak e volte com a pelagem dela.", tag="Opcional"}, [95]={npc="Morin Espreita Nuvem", tgt="Morin Espreita Nuvem"}, [96]={npc="Morin Espreita Nuvem", tgt="Morin Espreita Nuvem"}, [97]={npc="Morin Espreita Nuvem", tgt="Morin Espreita Nuvem", tag="Opcional"}, [98]={npc="Morin Espreita Nuvem", tgt="Morin Espreita Nuvem", tag="Opcional", desc="Abaixo do nível 12? Faça mais missões perto da mina."}, [99]={hint="Leve a Chave de Fio-afiado a Morin Espreita Nuvem, nos arredores da Aldeia Casco Sangrento.", tag="Opcional", desc="Abaixo do nível 12? Faça mais missões perto da mina."}, [100]={npc="Morin Espreita Nuvem", tgt="Morin Espreita Nuvem", tag="Opcional", desc="Abaixo do nível 12? Faça mais missões perto da mina."}, [101]={npc="Baine Casco Sangrento", tgt="Baine Casco Sangrento"}, [102]={npc="Ruul Garra da Águia", tgt="Ruul Garra da Águia"}, [103]={npc="Yaw Crina Cortante", tgt="Yaw Crina Cortante", tag="Opcional"}, [104]={npc="Baine Casco Sangrento", tgt="Baine Casco Sangrento"}, [105]={npc="Mull Chifre Troante", tgt="Mull Chifre Troante"}, [106]={npc="Mull Chifre Troante", tgt="Mull Chifre Troante", tag="Opcional"}, [107]={hint="Leve 8 Dentes de Lobos-da-pradaria alfas para Mull Chifre Troante na Aldeia Casco Sangrento.", tag="Opcional"}, [108]={npc="Mull Chifre Troante", tgt="Mull Chifre Troante", tag="Opcional"}, [109]={npc="Mull Chifre Troante", tgt="Mull Chifre Troante", tag="Opcional"}, [110]={hint="Use o Totem de Purificação Juba Agreste no Poço Juba Agreste, então fale novamente com Mull Chifre Troante.", tag="Opcional"}, [111]={npc="Mull Chifre Troante", tgt="Mull Chifre Troante", tag="Opcional"}, [112]={npc="Mull Chifre Troante", tgt="Mull Chifre Troante", tag="Opcional"}, [113]={npc="Skorn Nuvem Branca", tgt="Skorn Nuvem Branca", tag="Opcional"}, [114]={hint="Leve 4 Garras de Predador das Estepes para Melor Casco de Pedra no Penhasco do Trovão.", tag="Opcional"}, [115]={text="Desbloquear Penhasco do Trovão e continue até A Encruzilhada"}, [116]={text="Siga a estrada principal de Mulgore até Penhasco do Trovão. Pegue o elevador e aprenda ponto de voo de Tal (47.00, 49.83)."}, [117]={hint="Fale com Caerne Casco Sangrento no Penhasco do Trovão."}, [118]={hint="Peça uma audiência com o Grande Chefe Caerne Casco Sangrento no Penhasco do Trovão."}, [119]={npc="Caerne Casco Sangrento", tgt="Caerne Casco Sangrento"}, [120]={npc="Caerne Casco Sangrento", tgt="Caerne Casco Sangrento"}, [121]={npc="Caerne Casco Sangrento", tgt="Caerne Casco Sangrento", tag="Opcional"}, [122]={hint="Leve o Relatório de Chifre Troante ao Arquidruida Hamuul Runa Totem, no Penhasco do Trovão.", tag="Opcional"}, [123]={npc="Arquidruida Hamuul Runa Totem", tgt="Arquidruida Hamuul Runa Totem", tag="Opcional"}, [124]={npc="Melor Casco de Pedra", tgt="Melor Casco de Pedra", tag="Opcional"}, [125]={npc="Eylah Solchifre", tgt="Eylah Solchifre", tag="Opcional", desc="Compre todos os quatro materiais no blefe. Use o incenso em Platô dos Caçadores."}, [126]={hint="Compre um Maço de Ervas com Nida, a herborista, um Maço de Galhos de Cedro com Nata, a fornecedora de encantamento, Fio de Tendão com Mahu, o fornecedor de couraria, e Pederneira e Lenhas Cerimoniais com Naal, o fornecedor de culinária.", tag="Opcional", desc="Compre todos os qua