    ["01-6"] = {name="Clareiras de Tirisfal", nameA="Clareiras de Tirisfal: {a:159}", tips={{k="提醒", text="Se você não aceitou Informações cruciais, comece na pousada Montalvo e pegue o primeiro lote de missões.", s={{"Se você não aceitou Informações cruciais, comece na pousada Montalvo e pegue o primeiro lote de missões"}}}, {k="取捨", text="Faça os objetivos Scarlet, Spider e Grave Moss no circuito sudeste. Combine os murlocs da costa norte com as missões de Agamand. Entregue missões próximas e parta para A Encruzilhada no nível 12."}, {k="取捨", text="Compre Fio Grosso de um vendedor por O frio da morte pela pousada. Se você ainda precisar de peles de murloc da costa norte para Pelegos para os Renegados, termine-as em sua próxima viagem à costa."}, {k="取捨", text="Conclua ambas as missões locais Aurora Argêntea para desbloquear Bastilha de Bandarion (somente Orcs, Trolls e Morto-vivo). Alguns acompanhamentos são apenas Morto-vivo. Se você estiver indo direto para A Encruzilhada, saia após as duas missões locais.", s={{"Conclua ambas as missões locais Aurora Argêntea para desbloquear Bastilha de Bandarion (somente Orcs, Trolls e Morto-vivo)", {race={"Orc", "Troll", "Scourge"}}}, {"Alguns acompanhamentos são apenas Morto-vivo", {race={"Scourge"}}}, {"Se você estiver indo direto para A Encruzilhada, saia após as duas missões locais"}}}, {k="提醒", text="Abaixo do nível 12? Faça Guerra à Cruzada Escarlate, A cripta da família ou as missões Aurora Argêntea O emissário argênteo, A Seita dos malditos e Vestígios da guerra, dependendo da disponibilidade e de onde você estiver.", s={{"Abaixo do nível 12?"}, {"Faça Guerra à Cruzada Escarlate, A cripta da família ou as missões Aurora Argêntea O emissário argênteo, A Seita dos malditos e Vestígios da guerra, dependendo da disponibilidade e de onde você estiver"}}}}, danger={[1]="Fique atento aos zumbis e espíritos errantes no cemitério sudeste. Limpe ao longo da borda para não ficar preso."}, grind={[1]={mob="Missionário Escarlate", note="Rodízios normais espalhados a sudoeste de Montalvo. Puxe um inimigo de cada vez da borda durante as primeiras missões Cruzada Escarlate."}, [2]={mob="Espírito Errante", note="Mobs normais se aglomeram com Blood Zombies no cemitério sudeste. Cuidado com as patrulhas. Combine Patrulha da retaguarda com a missão de ervas do cemitério."}, [3]={mob="Neófito Sombrio", note="Densos mobs normais perto das missões Aurora Argêntea ao sudeste. Puxe um inimigo de cada vez da borda do acampamento para evitar os Dark Enforcers. Moer de 11 a 12."}}, supply={[1]={npc="Estalajadeira Geni"}, [2]={npc="Abel Hibérnias"}, [3]={npc="Estalajadeira Geni"}, [4]={npc="Sra. Hibérnias"}, [5]={npc="Doraso"}}, steps={[1]={npc="Necroguarda Simério", tgt="Necroguarda Simério"}, [2]={npc="Gordo", tgt="Gordo"}, [3]={hint="Roube 10 abóboras da fazenda a oeste, que fica ao norte de Plangemortis, e leve-as para o Boticário Joaquino em Montalvo."}, [4]={hint="Colha 3 Ervas-do-emo e entregue para o Boticário-júnior Hollanda, no cemitério de Montalvo."}, [5]={hint="Entregue os Documentos da Cruzada Escarlate ao Executor Zigano, em Montalvo."}, [6]={npc="Executor Zigano", tgt="Executor Zigano"}, [7]={npc="Boticário Joaquino", tgt="Boticário Joaquino"}, [8]={npc="Boticário-júnior Hollanda", tgt="Boticário-júnior Hollanda"}, [9]={text="vincule seu Pedra de Regresso com Estalajadeira Geni em Montalvo (61.72, 52.05)."}, [10]={npc="Boticário Joaquino", tgt="Boticário Joaquino"}, [11]={hint="Leve a Abóbora Inoculada para o Zelote Escarlate Capturado que esta sendo mantido no porão da Taberna Nó da Forca."}, [12]={npc="Zelote Escarlate Capturado", tgt="Zelote Escarlate Capturado"}, [13]={npc="Necroguarda Dinis", tgt="Necroguarda Dinis"}, [14]={npc="Magistrado Sevren", tgt="Magistrado Sevren"}, [15]={npc="Boticário Joaquino", tgt="Boticário Joaquino"}, [16]={npc="Boticário-júnior Hollanda", tgt="Boticário-júnior Hollanda"}, [17]={npc="Executor Zigano", tgt="Executor Zigano"}, [18]={npc="Executor Zigano", t