    [2606] = {n="Gosto não se discute", d="Marin Nublacuca quer que você fale com Sguisha em Geringontzan."},
    [2641] = {n="O Ingrediente Secreto de Sguisha", d="Sguisha, em Geringontzan, quer que você colete um Tragão Violeta e fale novamente com ela.", objs={"Tragão Violeta"}},
